insert into news_articles (category, title, source, body, icon, is_breaking, status, is_featured, is_trending, published_at) values
  ('politics', 'Inama Nkuru ya G7 Yatangiye: Abayobozi b''Ibihugu 7 Baganira ku Mahoro n''Ubukungu bw''Isi', 'BBC News', 'Abayobozi b''ibihugu birindwi bigize G7 batangiye inama nkuru y''iminsi itatu, bagamije kuganira ku mahoro mpuzamahanga n''uburyo bwo gukomeza ubukungu bw''isi mu gihe cy''ibibazo bitandukanye. Muri gahunda harimo n''ikiganiro ku mihindagurikire y''ikirere n''umutekano w''ibiribwa ku isi. Inama izasozwa n''itangazo rusange rigaragaza imyanzuro bahuriyeho, harimo n''imfashanyo ku bihugu bikennye.', 'earth', true, 'published', true, false, now() - interval '2 hours'),
  ('business', 'IMF Ivuga ko Afurika Izongera Ubukungu 4.2% muri 2026', 'Reuters', 'Ikigo mpuzamahanga cy''imari (IMF) cyatangaje ko ubukungu bw''ibihugu byo muri Afurika buteganyijwe kwiyongera ku kigero cya 4.2% mu mwaka wa 2026, kurenga ku bipimo byo mu bindi bice by''isi. Iyi terambere riterwa cyane cyane n''ubucukuzi bw''amabuye y''agaciro n''ihinduka ry''ikoranabuhanga mu bucuruzi. IMF yifuza ko ibihugu byakoresha neza aya mahirwe mu kongera imirimo ku rubyiruko.', 'chart-line', false, 'published', false, true, now() - interval '4 hours'),
  ('science', 'Ikizamini Gishya Gishobora Gukiza Miliyoni z''Abantu', 'CNN', 'Abahanga mu bumenyi bw''ubuzima batangaje ko basoje ikizamini cya mbere cy''umuti mushya ushobora gufasha kuvura indwara zandura zica abantu benshi buri mwaka, cyane cyane muri Afurika. Ibisubizo by''ikizamini byerekana ko umuti ufite akamaro kagaragara, ariko hakenewe ubushakashatsi bwinshi mbere yo kuwutangira ku baturage bose. Niba byemejwe, uyu muti ushobora kugera ku baturage mu myaka itatu iri imbere.', 'dna', false, 'published', false, true, now() - interval '6 hours'),
  ('sport', 'Real Madrid Yinjiye mu Makipe ya Kabiri ya Champions League', 'Sky Sports', 'Real Madrid yemeje ko yinjiye mu majyambere ya Champions League nyuma yo gutsinda umukino wayo wa nyuma mu itsinda. Umutoza w''ikipe yashimiye abakinnyi kubera imikino myiza bagaragaje mu minsi ishize. Ikipe izahura n''umwanzi wayo mu ndunduro zizakurikiraho mu mezi make aza.', 'trophy', false, 'published', false, true, now() - interval '8 hours'),
  ('world', 'Amerika n''Ubushinwa Bisubiranya Gutumanahana', 'Al Jazeera', 'Amerika n''Ubushinwa byatangaje ko bisubiranya ibiganiro by''ubucuruzi nyuma y''amezi menshi bidatumanaho neza. Impande zombi zivuga ko zifuza gushaka umuti ku bibazo by''imisoro ku bicuruzwa byinjizwa hagati yabyo. Abanyapolitiki bo ku isi bavuga ko iki cyemezo gishobora kugira uruhare mu guhumuriza isoko mpuzamahanga.', 'handshake', false, 'published', false, true, now() - interval '9 hours'),
  ('world', 'Ubushinwa Bwemeje Gufungura Inzira Nshya yo Gutumanahana n''Uburengerazuba', 'Reuters', 'Ubuyobozi bw''Ubushinwa bwatangaje ko bwemeje gufungura inzira nshya y''ibiganiro n''ibihugu by''Uburengerazuba, nyuma y''igihe kirekire hari ibibazo hagati yabo. Iyi ntambwe iteganyijwe gutangira n''inama y''abadipolomate bakuru mu byumweru bike biri imbere. Abasesenguzi bavuga ko iki cyemezo gishobora kugabanya ibyago by''intonganya z''ubucuruzi hagati y''impande ebyiri.', 'bank', false, 'published', false, false, now() - interval '1 hours'),
  ('africa', 'AU Itangaza Gahunda yo Gushyira Amashanyarazi mu Bihugu 30 by''Afurika', 'Al Jazeera', 'Umuryango w''Afurika Yunze Ubumwe (AU) watangaje gahunda nshya igamije gushyira amashanyarazi mu bihugu 30 bitarabigeraho, ikazatwara imyaka itanu. Iyi gahunda izashingira ku ngufu z''izuba n''amazi, kandi izafasha imiryango miriyoni nyinshi kubona amashanyarazi ku nshuro ya mbere. Ibihugu bimwe byatangiye kwiyandikisha kugira ngo bibashe kubona inkunga.', 'map', false, 'published', false, false, now() - interval '3 hours'),
  ('sport', '3 — 1: Real Madrid Yatsinze Bayern Munich', 'Sky Sports', 'Real Madrid yatsinze Bayern Munich amanota 3 kuri 1 mu mukino wakinnye ku mugoroba wa ejo, ikomeza urugendo rwiza muri Champions League. Ibitego byatsinzwe n''abakinnyi batatu batandukanye, aho igitego cya nyuma cyatsinzwe mu minota ya nyuma y''umukino. Uyu mukino wari umwe mu yagaragaje imikino myiza y''ibipimo bibiri.', 'trophy', false, 'published', false, false, now() - interval '5 hours'),
  ('science', 'Ubushakashatsi Bushya Bwerekana Uko Ikirere cy''Isi Cyahindutse mu Myaka 10,000', 'CNN', 'Ubushakashatsi bushya bwakozwe n''abahanga mu bumenyi bw''ikirere bwerekanye uko ikirere cy''isi cyahindutse mu myaka 10,000 ishize, bakoresheje ibimenyetso byavuye mu barafu n''amabuye. Iyi mibare igaragaza ko ihindagurika ry''iki gihe rifite umuvuduko utigeze ubaho mu mateka. Abashakashatsi bavuga ko iyi nyandiko izafasha mu gutegura politiki nziza ku kirere.', 'dna', false, 'published', false, false, now() - interval '6 hours'),
  ('business', 'Igiciro cy''Ibikomoka kuri Peteroli Cyongeye Kuzamura Ubukungu bw''Uburayi', 'BBC', 'Igiciro cy''ibikomoka kuri peteroli cyazamutse ku isoko mpuzamahanga, bigatuma ibihugu byinshi byo mu Burayi bihura n''ikibazo cyo kongera igiciro cy''ingufu. Ibi bishobora kugira ingaruka ku bucuruzi n''ubukungu bw''imiryango myinshi mu gihe cy''itumba. Guverinoma zimwe zatangiye gutegura ingamba zo gufasha abaturage bakennye.', 'chart-line', false, 'published', false, false, now() - interval '7 hours'),
  ('politics', 'Inteko Ishinga Amategeko Yemeje Itegeko Rishya ry''Uburezi', 'The New Times', 'Inteko Ishinga Amategeko yemeje itegeko rishya rigamije kunoza uburezi mu mashuri abanza n''ayisumbuye, harimo n''ivugurura ry''inyigisho z''ikoranabuhanga. Iri tegeko rizatangira gushyirwa mu bikorwa mu mwaka utaha w''amashuri. Abarimu bemejwe ko bazahabwa amahugurwa mbere yo gutangira gukoresha uburyo bushya.', 'gavel', false, 'published', false, false, now() - interval '9 hours'),
  ('africa', 'Kigali Yakiriye Inama Nkuru ya Tekinoloji Yitabiriwe n''Ibihugu 40', 'KT Press', 'Umujyi wa Kigali wakiriye inama nkuru mpuzamahanga y''ikoranabuhanga yitabiriwe n''intumwa ziturutse mu bihugu 40. Abitabiriye bagaranije uburyo Afurika ishobora gukoresha ikoranabuhanga mu kunoza ubukungu n''imibereho y''abaturage. Rwanda yashimiwe kubera uruhare rwayo mu iterambere ry''ikoranabuhanga muri aka karere.', 'city', false, 'published', false, false, now() - interval '11 hours'),
  ('business', 'Banki Nkuru y''u Rwanda Yagabanyije Inyungu ku Nguzanyo', 'The New Times', 'Banki Nkuru y''u Rwanda yatangaje ko igabanyije igipimo cy''inyungu ku nguzanyo, igamije guteza imbere ishoramari n''ubucuruzi bw''ibigo bito n''ibiciriritse. Iki cyemezo giteganyijwe gufasha abanyarwanda benshi kubona inguzanyo ku giciro gikwiye. Inzobere mu bukungu zishimira iki cyemezo, zivuga ko gishobora gukangura ubukungu mu gihe gito.', 'cash-multiple', false, 'published', false, false, now() - interval '13 hours'),
  ('world', 'Umuriro wo mu Mashyamba Wagize Ingaruka ku Bantu Ibihumbi mu Burayi', 'Reuters', 'Umuriro ukomeye wo mu mashyamba wagize ingaruka ku baturage ibihumbi byinshi mu bice bimwe by''Uburayi, utuma abenshi bimurwa mu mutekano. Abazimya umuriro bakomeje kurwana n''inkongi, bafashijwe n''ibindi bihugu byoherereje ubufasha. Ubuyobozi bwasabye abaturage kwitondera amabwiriza y''umutekano mu gihe umuriro ukiriho.', 'fire', false, 'published', false, false, now() - interval '38 minutes'),
  ('science', 'Icyogajuru Gishya Cyoherejwe mu Kirere Kizafasha Kumenya Ibihe', 'BBC', 'Icyogajuru gishya cyoherejwe mu kirere cyagenewe gufasha abahanga kumenya neza ihinduka ry''ibihe ku isi hose. Iki cyogajuru gizakoresha ikoranabuhanga rigezweho mu gukusanya amakuru ajyanye n''imiterere y''ikirere buri munsi. Abahanga bizeye ko amakuru azavamo azafasha ibihugu gutegura neza ibiza bishobora guterwa n''ikirere.', 'rocket-launch', false, 'published', false, false, now() - interval '15 hours');
